#include <string.h>

char* get_url_for_query(const char* api_url, const char* user_id) {
    if (user_id == NULL || strlen(user_id) == 0) {
        return NULL;
    }

    // Sanitize user_id to prevent path traversal or injection attacks
    // Only allow alphanumeric characters and hyphens
    char sanitized_user_id[256];
    size_t sanitized_len = 0;
    for (size_t i = 0; i < strlen(user_id); i++) {
        char c = user_id[i];
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-') {
            sanitized_user_id[sanitized_len++] = c;
        }
    }
    sanitized_user_id[sanitized_len] = '\0';

    // Check if any character was sanitized (i.e., user_id contained invalid characters)
    if (sanitized_len != strlen(user_id)) {
        return NULL;
    }

    size_t api_len = strlen(api_url);
    size_t user_len = strlen(user_id);
    size_t total_len = api_len + user_len + 1; // +1 for the slash

    char* url = (char*)malloc(total_len * sizeof(char));
    if (url == NULL) {
        return NULL;
    }

    snprintf(url, total_len, "%s/%s", api_url, user_id);

    return url;
}
